<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {request} from '../api'
import MathText from './MathText.vue'
const props=defineProps({user:Object}),emit=defineEmits(['reply','message'])
const direct=ref([]),replies=ref([]),error=ref(''),filter=ref('received')
let timer,active=true
async function load(){try{const [d,r]=await Promise.all([request('group','/group/messages/me'),request('group','/group/replies/me')]);if(active){direct.value=d;replies.value=r;error.value=''}}catch(e){if(active)error.value=e.message}}
async function read(m){try{await request('group',`/group/messages/${m.id}/read`,'PATCH');await load()}catch(e){error.value=e.message}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load()},15000)});onUnmounted(()=>{active=false;clearInterval(timer)})
</script>
<template><section class="group-messages"><div class="section-head"><div><small class="eyebrow">GROUP INBOX</small><h2>与你有关的消息</h2></div><button class="secondary" @click="load">刷新消息</button></div><p class="note">成员消息仅发送者和收件人可见；讨论中指定回复给你的内容也会汇集在这里。</p><p v-if="error" class="error">{{error}}</p><div class="message-tabs"><button :class="{selected:filter==='received'}" @click="filter='received'">收到的消息</button><button :class="{selected:filter==='sent'}" @click="filter='sent'">我发出的消息</button></div><div class="inbox-columns"><div><h3>成员消息</h3><p v-if="!direct.some(m=>filter==='received'?m.recipient_id===user.id:m.sender_id===user.id)" class="empty">暂无消息。可在联网成员页选择同伴发起交流。</p><article v-for="m in direct.filter(m=>filter==='received'?m.recipient_id===user.id:m.sender_id===user.id)" :key="m.id" class="card inbox-card"><div class="section-head"><strong>{{filter==='received'?m.sender_nickname:'发给 '+m.recipient_nickname}}</strong><span class="badge">{{m.is_read?'已读':'未读'}}</span></div><small class="muted">{{new Date(m.created_at).toLocaleString('zh-CN')}}</small><MathText :text="m.body"/><div class="message-actions"><button v-if="filter==='received'" class="secondary" @click="emit('message',{user_id:m.sender_id,nickname:m.sender_nickname})">回复 {{m.sender_nickname}}</button><button v-if="filter==='received'&&!m.is_read" class="secondary" @click="read(m)">标记已读</button></div></article></div><div v-if="filter==='received'"><h3>定向讨论回复</h3><p v-if="!replies.length" class="empty">暂无指定给你的讨论回复。</p><article v-for="r in replies" :key="r.id" class="card inbox-card"><strong>{{r.nickname}} 回复了你</strong><small class="muted">{{r.title}} · {{new Date(r.created_at).toLocaleString('zh-CN')}}</small><MathText :text="r.body"/><button class="secondary" @click="emit('reply',r.discussion_id)">查看讨论并回复 →</button></article></div></div></section></template>
